namespace QaTracker.Application.Abstractions;

/// <summary>Where attachment files live (local folder now; any blob store later). Paths are relative and generated by us.</summary>
public interface IFileStorage
{
    Task SaveAsync(string path, Stream content, CancellationToken cancellationToken);

    /// <summary>The file, or null when it does not exist.</summary>
    Stream? OpenRead(string path);

    /// <summary>Removes the file if it exists.</summary>
    Task DeleteAsync(string path, CancellationToken cancellationToken);
}

/// <summary>Small preview of an image (attachment galleries, reports).</summary>
public interface IThumbnailGenerator
{
    /// <summary>File extension of generated thumbnails, e.g. ".webp".</summary>
    string Extension { get; }

    string ContentType { get; }

    /// <summary>A thumbnail of the image, or null when it cannot be decoded or is too large to decode safely.</summary>
    byte[]? Create(ReadOnlySpan<byte> image);
}

/// <summary>Short-lived signed URLs, so &lt;img src&gt; and download links work without an Authorization header.</summary>
public interface IAttachmentUrlSigner
{
    /// <summary>"/api/attachments/12?u=5&amp;exp=…&amp;sig=…" (or …/12/thumbnail?…) for this user.</summary>
    string Sign(int attachmentId, bool thumbnail, int userId);

    /// <summary>The signing user when the signature is valid and not expired; otherwise null.</summary>
    int? Verify(int attachmentId, bool thumbnail, int userId, long expires, string signature);
}
